-- 시연용 오늘의 퀴즈 30문제. alembic upgrade head(0023) 후 실행. 다시 실행해도 slug 기준으로 갱신된다.
-- scripts/build_quiz_seed.py가 생성한 파일이므로 직접 고치지 않는다.
BEGIN;
ON CONFLICT (slug) DO UPDATE SET demo_order = EXCLUDED.demo_order, category = EXCLUDED.category, quiz_type = EXCLUDED.quiz_type, label = EXCLUDED.label, question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, concept = EXCLUDED.concept, source = EXCLUDED.source, source_ref = EXCLUDED.source_ref, as_of_date = EXCLUDED.as_of_date, updated_at = now();
COMMIT;
